{
  "conversations": [
    {
      "title": "Describe my symptoms",
      "lines": [
        { "speaker": "you", "text": "My stomach hurts." },
        { "speaker": "partner", "text": "What's wrong?" },
        { "speaker": "you", "text": "I have nausea." },
        { "speaker": "you", "text": "I have diarrhea.", "or": true },
        { "speaker": "partner", "text": "How long has it hurt?" },
        { "speaker": "you", "text": "Since this morning." },
        { "speaker": "you", "text": "Since yesterday.", "or": true }
      ]
    },
    {
      "title": "Ask about medication",
      "lines": [
        { "speaker": "you", "text": "What do you suggest for stomachache?" },
        { "speaker": "partner", "text": "Do you want capsules or liquid?" },
        { "speaker": "you", "text": "Capsules, please." },
        { "speaker": "you", "text": "Liquid, please.", "or": true },
        { "speaker": "partner", "text": "Take two pills after meals." },
        { "speaker": "you", "text": "How many times a day?" },
        { "speaker": "partner", "text": "Three times a day." }
      ]
    },
    {
      "title": "Explain allergies",
      "lines": [
        { "speaker": "you", "text": "Am I allergic to this?" },
        { "speaker": "partner", "text": "Do you have any allergies?" },
        { "speaker": "you", "text": "I'm allergic to penicillin." },
        { "speaker": "you", "text": "I don't have any allergies.", "or": true },
        { "speaker": "partner", "text": "This is safe for you." },
        { "speaker": "you", "text": "Thank you." }
      ]
    }
  ],
  "vocab": [
    "stomach",
    "nausea",
    "diarrhea",
    "morning",
    "capsule",
    "liquid",
    "pills",
    "meals",
    "allergic",
    "penicillin",
    "safe",
    "suggest"
  ]
}
